//
// Proof-of-concept for a generic knot drawing algorithm with Bezier curves. This is not Truchet :) 
//
// The lattice used is a voronoise grid. In fact the shader was originally forked from IQ's https://www.shadertoy.com/view/MslGD8
// Toggle DRAW_CELLS to view the grid.
//
// Inside each cell, each edge center tries to connect to the next edge center on its right with a Bezier curve.
// See https://entrelacs.net/The-basics.html for a basic explanation of the approach used to connect the cells.
//


//#define DRAW_CELLS
//#define FAST_BEZIER

const float kKnotWidth = 0.12;
const float kNoiseFactor = 0.2; // [0.0 - 0.5], big values break the algo
const float kEdgeAngle = 3.1415926*0.35; // [0.0 - PI/2]
const vec2 kEdgeSC = vec2(cos(kEdgeAngle),sin(kEdgeAngle));

//-------------------------------------------------------------------
// Utils
float dot2( vec2 v ) { return dot(v,v); }
float cro( vec2 a, vec2 b ) { return a.x*b.y-a.y*b.x; }
float cos_acos_3( float x ) { x=sqrt(0.5+0.5*x); return x*(x*(x*(x*-0.008972+0.039071)-0.107074)+0.576975)+0.5; } // https://www.shadertoy.com/view/WltSD7

vec2 hash( vec2 p )
{
    p = vec2(dot(p,vec2(127.1,311.7)),
             dot(p,vec2(269.5,183.3)));
    return fract(sin(p)*18.5453);
}
float hash21( vec2 p )
{
    vec2 h = hash(p);
    return h.x + h.y;
}

vec3 hsv2rgb( in vec3 c )
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
    return c.z * mix( vec3(1.0), rgb, c.y);
}

vec3 pal(float t, vec3 a, vec3 b, vec3 c, vec3 d)
{
    return a + b*cos( 6.28318*(c*t+d) );
}
vec3 palette(float t)
{
    return pal( t, vec3(0.5,0.8,0.8), vec3(0.5,0.2,0.2), vec3(1.0), vec3(0.525,1.0238,0.064) );
}

//-------------------------------------------------------------------
// Bezier code from IQ, see https://www.shadertoy.com/view/MlKcDD
#ifdef FAST_BEZIER
vec2 sdBezier( vec2 p, vec2 v0, vec2 v1, vec2 v2 )
{
	vec2 i = v0 - v2;
    vec2 j = v2 - v1;
    vec2 k = v1 - v0;
    vec2 w = j-k;

	v0-= p; v1-= p; v2-= p;

	float x = cro(v0, v2);
    float y = cro(v1, v0);
    float z = cro(v2, v1);

	vec2 s = 2.0*(y*j+z*k)-x*i;

    float r =  (y*z-x*x*0.25)/dot2(s);
    float t = clamp( (0.5*x+y+r*dot(s,w))/(x+y+z),0.0,1.0);

    vec2 d = v0+t*(k+k+t*w);
    //outQ = d + p;
	return vec2(length(d), t);
}
#else
// signed distance to a quadratic bezier
vec2 sdBezier( vec2 pos, vec2 A, vec2 B, vec2 C )
{    
    vec2 a = B - A;
    vec2 b = A - 2.0*B + C;
    vec2 c = a * 2.0;
    vec2 d = A - pos;

    // cubic to be solved (kx*=3 and ky*=3)
    float kk = 1.0/dot(b,b);
    float kx = kk * dot(a,b);
    float ky = kk * (2.0*dot(a,a)+dot(d,b))/3.0;
    float kz = kk * dot(d,a);      

    float res = 0.0;
    float sgn = 0.0;

    float p  = ky - kx*kx;
    float q  = kx*(2.0*kx*kx - 3.0*ky) + kz;
    float p3 = p*p*p;
    float q2 = q*q;
    float h  = q2 + 4.0*p3;

    if( h>=0.0 ) 
    {   // 1 root
        h = sqrt(h);
        vec2 x = (vec2(h,-h)-q)/2.0;

        #if 0
        // When p≈0 and p<0, h-q has catastrophic cancelation. So, we do
        // h=√(q²+4p³)=q·√(1+4p³/q²)=q·√(1+w) instead. Now we approximate
        // √ by a linear Taylor expansion into h≈q(1+½w) so that the q's
        // cancel each other in h-q. Expanding and simplifying further we
        // get x=vec2(p³/q,-p³/q-q). And using a second degree Taylor
        // expansion instead: x=vec2(k,-k-q) with k=(1-p³/q²)·p³/q
        if( abs(p)<0.001 )
        {
            float k = p3/q;              // linear approx
          //float k = (1.0-p3/q2)*p3/q;  // quadratic approx 
            x = vec2(k,-k-q);  
        }
        #endif

        vec2 uv = sign(x)*pow(abs(x), vec2(1.0/3.0));
        float t = uv.x + uv.y;

		// from NinjaKoala - single newton iteration to account for cancellation
        t -= (t*(t*t+3.0*p)+q)/(3.0*t*t+3.0*p);

        t = clamp( t-kx, 0.0, 1.0 );
        vec2  w = d+(c+b*t)*t;
        //outQ = w + pos;
        res = dot2(w);
    	//sgn = cro(c+2.0*b*t,w);

        return vec2(sqrt(res)/*sign(sgn)*/, t);
    }

    // 3 roots
    float z = sqrt(-p);
    #if 0
    float v = acos(q/(p*z*2.0))/3.0;
    float m = cos(v);
    float n = sin(v);
    #else
    float m = cos_acos_3( q/(p*z*2.0) );
    float n = sqrt(1.0-m*m);
    #endif
    n *= sqrt(3.0);
    float th = 0.0;
    vec3  t = clamp( vec3(m+m,-n-m,n-m)*z-kx, 0.0, 1.0 );
    vec2  qx=d+(c+b*t.x)*t.x; float dx=dot2(qx), sx=cro(a+b*t.x,qx);
    vec2  qy=d+(c+b*t.y)*t.y; float dy=dot2(qy), sy=cro(a+b*t.y,qy);
    if( dx<dy ) {res=dx;sgn=sx;th=t.x;/*outQ=qx+pos;*/} else {res=dy;sgn=sy;th=t.y;/*outQ=qy+pos;*/}

    return vec2(sqrt(res)/*sign(sgn)*/, th);
}
#endif

//-------------------------------------------------------------------
// ray-ray intersection
vec2 rayRay(vec2 as, vec2 ad, vec2 bs, vec2 bd)
{
    float dx = bs.x - as.x;
    float dy = bs.y - as.y;
    float det = bd.x * ad.y - bd.y * ad.x;
    if (abs(det) > 1e-4) 
    { 
        float u = (dy * bd.x - dx * bd.y) / det;
        float v = (dy * ad.x - dx * ad.y) / det;
        return vec2(u, v);
    }
    // wrong but safe fallback in our case
    return vec2(0.0);
}

// basics for voronoise
vec2 getCellOffset(vec2 cid)
{
    vec2 o = hash( cid );
    return (0.5 + kNoiseFactor*sin(1.0*iTime+6.2831*o));
}


// returns distance + cell id
vec3 getClosestCell( in vec2 p )
{
    vec2 n = floor( p );
    vec2 f = fract( p );

	vec3 m = vec3( 8.0 );
    for( int j=-1; j<=1; j++ )
    for( int i=-1; i<=1; i++ )
    {
        vec2  off = vec2( float(i), float(j) );
        vec2  cid = n + off;
	    vec2  r = off - f + getCellOffset(cid);
		float d = dot( r, r );
        if( d < m.x )
            m = vec3( d, cid );
    }

    return vec3( sqrt(m.x), m.yz );
}

//-------------------------------------------------------------------
// returns dist to nearest bezier curve, t on curve, and starting+ending cells hid
vec4 sdKnots(vec2 p, vec3 m)
{
    vec4 edges[8] = vec4[](vec4(0.), vec4(0.), vec4(0.), vec4(0.), vec4(0.), vec4(0.), vec4(0.), vec4(0.));
    vec2 offs[8] = vec2[](vec2(-1.,-1.), vec2(0.,-1), vec2(1.,-1.), vec2(1.,0.), vec2(1.,1.), vec2(0.,1.), vec2(-1.,1.), vec2(-1.,0.));

    vec2 n = m.yz; // current cell processed, all coords are local to it
    vec2 cn = getCellOffset(n);

    // first construct edges surrounding the cell (edge 'center' + normal dir)
    for(int i=0; i<8; i++)
    {
        vec2 cid = n + offs[i];
        vec2 cc = offs[i] + getCellOffset(cid);
        edges[i].xy = (cn + cc)*0.5; // center, that is on separating axis between the two cells
        edges[i].zw = normalize(cn - cc); // orthogonal dir of edge
    }

    // track left and right space available on each edge
    vec2 minmax[8] = vec2[](vec2(-1.,1.),vec2(-1.,1.),vec2(-1.,1.),vec2(-1.,1.),vec2(-1.,1.),vec2(-1.,1.),vec2(-1.,1.),vec2(-1.,1.));
    for(int i=0; i<8; i++)
    {
        vec4 ecurr = edges[i];
        for(int j=1; j<3; j++)
        {
            vec4 enext = edges[(i+j)%8];
            vec2 cr = vec2(ecurr.w, -ecurr.z); // right vector (ie. along edge dir)
            vec2 nr = vec2(enext.w, -enext.z);

            // check where edges overlap
            vec2 uv = rayRay(ecurr.xy, cr, enext.xy, nr);
            minmax[i].y = min(minmax[i].y, uv.x);
            minmax[(i+j)%8].x = max(minmax[(i+j)%8].x, uv.y);
        }
    }

    vec2 dtm = vec2(8.);
    float hn = hash21(n);
    float hi = 0.;
    float hj = 0.;

    // connect edges with spline
    for(int i=0; i<8; i++)
    {
        if(minmax[i].y - minmax[i].x < kKnotWidth*3.0)
            continue; // not enough space to connect from this edge

        for(int j=1; j<7; j++)
        {
            int jo = (i+j)%8;
            if(minmax[jo].y - minmax[jo].x < kKnotWidth*3.0)
                continue; // not enough space to connect to this edge

            vec4 ecurr = edges[i];
            vec4 enext = edges[jo];

            vec2 cr = vec2(ecurr.w, -ecurr.z); // right vector (ie. along edge dir)
            vec2 nr = vec2(enext.w, -enext.z);
            vec2 b0 = ecurr.xy + cr*((minmax[i].y + minmax[i].x)*0.5); // spline startpoint
            vec2 b1 = enext.xy + nr*((minmax[jo].y + minmax[jo].x)*0.5); // spline endpoint

            vec2 v0 = cr*kEdgeSC.x + ecurr.zw*kEdgeSC.y;
            vec2 v1 = nr*(-kEdgeSC.x) + enext.zw*kEdgeSC.y;
            vec2 bmid = (b0 + 0.55*v0 + b1 + 0.55*v1)*0.5;

            vec2 dt = sdBezier( p-n, b0, bmid, b1);
            if(dt.x < kKnotWidth && dt.y < dtm.y)
            {
                dtm = dt;
                float hfr = hash21(n + offs[i]);
                float hto = hash21(n + offs[jo]);
                hi = hn >= hfr ? hn : hfr;
                hj = hto >= hn ? hto : hn;
            }
            break;
        }
    }

    return vec4(dtm, hi, hj);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = fragCoord.xy/max(iResolution.x,iResolution.y);

    // compute voronoi pattern
    vec2 sp = (20.0 + 6.0*sin(0.2*iTime))*p;

    vec3 c = getClosestCell( sp );

    vec4 dtij = sdKnots( sp, c);
    float dk = smoothstep(0.0, kKnotWidth, dtij.x);

    // colorize
#ifdef DRAW_CELLS
    vec3 colcell = 0.6*palette( hash21(c.yz) );
#else
    vec3 colcell = vec3(0.);
#endif

    vec3 colknot1 = palette( dtij.z );
    vec3 colknot2 = palette( dtij.w );
    vec3 colknot = mix(colknot1, colknot2, dtij.y);

    vec3 col = hsv2rgb( mix(colknot, colcell, pow(dk,3.0)) );

#ifdef DRAW_CELLS
    col -= (1.0-smoothstep( 0.08, 0.085, c.x));
#endif

    fragColor = vec4( col, 1.0 );
}
